UPDATE tb_group_tag
SET is_deleted = 1
WHERE group_id = #{groupId}

mapper.select:
SELECT tt.id AS tagId, tt.name AS tagName, tt.icon AS icon, tt.color AS color, tt.is_deleted AS deleted, -- 根据标签删除状态应用不同的统计逻辑 COUNT( c.group_id) AS count, COUNT( DISTINCT CASE WHEN tg.archived=2 THEN tg.id ELSE NULL END) as archivedCount, COUNT(DISTINCT CASE WHEN tg.archived IN (0, 1) THEN tg.id ELSE NULL END) as unArchivedCount FROM tb_label tt -- 左连接确保未删除标签即使无关联数据也能保留 LEFT JOIN tb_group_tag t ON tt.id = t.tag_id AND t.is_deleted = 0 LEFT JOIN ( select ttc.group_id from tb_create_group ttc LEFT JOIN tb_group_extends ttg on ttc.group_id = ttg.group_id
ttg.group_type = 2
and ttc.department_id IN
#{orgId}
AND ( ttc.user_ids LIKE CONCAT('%', #{userId}, '%')
OR
user_ids LIKE CONCAT('%', #{postId}, '%')
)
AND ttc.department_id IN
#{departmentCode}
AND ttc.create_time >= #{startTime}
AND ttc.create_time <= CONCAT(#{endTime}, ' 23:59:59')
) c ON t.group_id = c.group_id LEFT JOIN tb_group_extends tg on c.group_id = tg.group_id
GROUP BY tt.id, tt.name, tt.is_deleted -- 筛选条件：未删除标签全部显示 或 已删除标签有统计数据时显示 HAVING tt.is_deleted = 0 -- 未删除标签全部显示（包括tagCount=0） OR (tt.is_deleted = 1 AND count > 0) -- 已删除标签仅显示有数据的 ORDER BY deleted ASC, -- 未删除标签排在前 tagId ASC

SELECT DISTINCT t.tag_id AS tagIds FROM tb_create_group c
INNER JOIN tb_group_tag t ON c.group_id = t.group_id AND t.is_deleted = 0


       and  c.department_id IN

            #{orgId}




       and  t.create_user_id = #{userId}

SELECT 1 as tagId, '未设置标签' as tagName, null as icon, null as color, 0 as deleted, -- 根据标签删除状态应用不同的统计逻辑 COUNT( c.group_id) AS count, COUNT( DISTINCT CASE WHEN tg.archived=2 THEN tg.id ELSE NULL END) as archivedCount, COUNT(DISTINCT CASE WHEN tg.archived IN (0, 1) THEN tg.id ELSE NULL END) as unArchivedCount FROM tb_create_group c LEFT JOIN tb_group_extends tg on c.group_id = tg.group_id LEFT JOIN tb_group_tag t ON t.group_id = c.group_id AND t.is_deleted = 0
t.id is null and tg.group_type = 2
and department_id IN
#{orgId}
AND ( user_ids LIKE CONCAT('%', #{userId}, '%')
OR
user_ids LIKE CONCAT('%', #{postId}, '%')
)
AND department_id IN
#{departmentCode}
AND create_time >= #{startTime}
AND create_time <= CONCAT(#{endTime}, ' 23:59:59')

SELECT 0 as tagId, '全部' as tagName, 'fas fa-home' as icon, 'rgba(38, 78, 209, 1)' as color, 0 as deleted, COUNT(c.group_id) AS count, COUNT(DISTINCT CASE WHEN tg.archived=2 THEN tg.id ELSE NULL END) as archivedCount, COUNT(DISTINCT CASE WHEN tg.archived IN (0, 1) THEN tg.id ELSE NULL END) as unArchivedCount FROM tb_create_group c LEFT JOIN tb_group_extends tg on c.group_id = tg.group_id
tg.group_type = 2
and c.department_id IN
#{orgId}
AND ( c.user_ids LIKE CONCAT('%', #{userId}, '%')
OR
c.user_ids LIKE CONCAT('%', #{postId}, '%')
)
AND c.department_id IN
#{departmentCode}
AND c.create_time >= #{startTime}
AND c.create_time <= CONCAT(#{endTime}, ' 23:59:59')

select t.id,t.name,gt.group_id from tb_label t join tb_group_tag gt on t.id = gt.tag_id and gt.is_deleted = 0 join tb_create_group c on gt.group_id = c.group_id join tb_group_extends tg on c.group_id = tg.group_id
tg.archived = 2
AND gt.gmt_created <= #{endTime}
AND c.department_id IN
#{departmentCode}
